diff --git a/src/smooth/ftgrays.c b/src/smooth/ftgrays.c
index 53948d2..bb5497f 100644
--- a/src/smooth/ftgrays.c
+++ b/src/smooth/ftgrays.c
@@ -1881,7 +1881,12 @@ typedef ptrdiff_t  FT_PtrDist;
     while ( 1 )
     {
       size_t  n;
-      TCoord  i, count = ras.max_ey - ras.min_ey;
+      TCoord  i, height = ras.max_ey - ras.min_ey;
+
+      /* One list head per contour.  Closing a contour inserts a */
+      /* cell immediately, and a band only a few rows tall would */
+      /* otherwise be split.                                     */
+      TCoord  count = height + (TCoord)ras.outline.n_contours;


       /* memory management: zero out and skip ycells */
@@ -1916,10 +1921,10 @@ typedef ptrdiff_t  FT_PtrDist;
         goto Exit;

       /* render pool overflow, reduce the render band by half */
-      count >>= 1;
+      height >>= 1;

       /* this happens only if the rendering pool is too small */
-      if ( count == 0 )
+      if ( height == 0 )
       {
         FT_TRACE7(( "gray_convert_glyph: rotten glyph\n" ));
         error = FT_THROW( Raster_Overflow );
@@ -1927,7 +1932,7 @@ typedef ptrdiff_t  FT_PtrDist;
       }

       *band++     = ras.min_ey;
-      ras.min_ey += count;
+      ras.min_ey += height;
     }

   Exit:

diff --git a/src/smooth/ftgrays.c b/src/smooth/ftgrays.c
index 5dbb2b3..a9d785b 100644
--- a/src/smooth/ftgrays.c
+++ b/src/smooth/ftgrays.c
@@ -2025,8 +2025,10 @@ typedef ptrdiff_t  FT_PtrDist;
     if ( ras.min_ex >= ras.max_ex || ras.min_ey >= ras.max_ey )
       return Smooth_Err_Ok;

-    /* allocate memory based on empirical estimate from CJK fonts */
-    estimate = ( ras.max_ex - ras.min_ex + ras.max_ey - ras.min_ey ) * 10UL;
+    /* Both axes are counted, so the empirical factor of ten  */
+    /* double-counts the long side.  Five cells per perimeter  */
+    /* pixel still covers the CJK glyphs that motivated it.    */
+    estimate = ( ras.max_ex - ras.min_ex + ras.max_ey - ras.min_ey ) * 5UL;
     if ( estimate > FT_MAX_GRAY_POOL )
     {
       FT_Error   error;

